(entry: ResizeObserverEntry) => {
        //judge whether parent or self display none
        let inRenderTree: boolean;
        if (entry.borderBoxSize) {
            inRenderTree = !(entry.borderBoxSize[0].blockSize === 0 && entry.borderBoxSize[0].inlineSize === 0);
        } else {
            inRenderTree = !(entry.contentRect.height === 0 && entry.contentRect.width === 0);
        }

        let height = 0;
        if (entry.borderBoxSize) {
            height = Math.ceil(entry.borderBoxSize[0].blockSize);
        } else {
            const target = entry.target as HTMLElement;
            height = target.clientHeight;
        }

        return {
            isShown: inRenderTree, height
        };
    }

(raw: string) => {
        if (raw.startsWith("#")) {
            return {
                hsva: hexToHsva(raw),
                rgba: hexToRgba(raw),
                hex: raw
            };
        } else if (raw.startsWith('rgba')) {
            const rgba = rgbaStringToRgba(raw);
            return {
                hsva: rgbaStringToHsva(raw),
                rgba: rgba,
                hex: rgbaToHex(rgba)
            };
        } else if (raw.startsWith("rgb")) {
            const rgba = rgbStringToRgba(raw);
            return {
                hsva: rgbStringToHsva(raw),
                rgba: rgba,
                hex: rgbaToHex(rgba)
            };
        } else if (raw.startsWith("hsv")) {
            const hsva = hsvaStringToHsva(raw);
            const rgba = hsvaToRgba(hsva);
            const hex = hsvaToHex(hsva);
            return {
                hsva,
                rgba,
                hex
            };
        } else {
            throw new Error("Semi ColorPicker: error on static colorStringToValue method, input value is invalid: " + raw);
        }
    }

